///////// 2. 초기화 영역 /////////
scwin.onpageload = function(e) {
    try {
        let arrPar = $p.getParentWindow().scwin.fn_GetParKisCd();
        ibx_coSnm.setValue((arrPar.length > 0) ? arrPar[0] : "");
        if (ibx_coSnm.getValue() !== "") {
            scwin.search();
        } else {
            ibx_coSnm.focus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.onpageload" });
    }
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.btn_search_onclick = function() {
    try {
        // 조회 버튼 클릭
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.btn_search_onclick" });
    }
};

scwin.btn_confirm_onclick = function() {
    try {
        // 확인버튼 클릭
        scwin.setParam();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.btn_confirm_onclick" });
    }
};

scwin.btn_Close_onclick = async function() {
    try {
        // 닫기 버튼 클릭
        $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.btn_Close_onclick" });
    }
};

scwin.ibx_coSnm_onkeydown = function(e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.ibx_coSnm_onkeydown" });
    }
};

scwin.btn_stdIndCd_onclick = function() {
    try {
        // 업종검색 팝업 오픈
        scwin.stdIndSrchOpen();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.btn_stdIndCd_onclick" });
    }
};

scwin.btn_affCoCd_onclick = function() {
    try {
        // 기업집단검색 팝업 오픈
        scwin.affCoCdSrchOpen();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.btn_affCoCd_onclick" });
    }
};

scwin.ibx_entprGrpNm_onkeydown = function() {
    try {
        // 기업집단검색 팝업 오픈
        if (event.keyCode === 13) {
            scwin.affCoCdSrchOpen();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.ibx_entprGrpNm_onkeydown" });
    }
};

scwin.ibx_entprGrpNm_onviewchange = function (info) {
    try {
        tbx_entprGrpCd.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.ibx_entprGrpNm_onviewchange" });
    }
};

scwin.ibx_stdIndNm_onviewchange = function (info) {
    try {
        tbx_stdIndCd.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.ibx_stdIndNm_onviewchange" });
    }
};

scwin.grd_ComList_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.setParam(rowIndex);	
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.grd_ComList_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.sbm_comList_submitdone = function (e) {
    // if (dlt_comListRes.errorMsg) {
    //     alert(dlt_comListRes.errorMsg);
    // } else {
    //     tbx_totCnt.setValue("총 " + rowcount + " 건");
    // }
    dlt_comListRes.setJSON(e.responseJSON.body);
    tbx_totCnt.setValue(dlt_comListRes.getRowCount());
};

scwin.sbm_comList_submiterror = function (e) {
    // $c.stf.alert_error(dlt_comListRes);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_comListRes.removeAll();
    tbx_totCnt.setValue("0");
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    if (ibx_coSnm.getValue() === "" && sbx_corpRegTyp.getValue() === "" && tbx_stdIndCd.getValue() === "" && tbx_entprGrpCd.getValue() === "") {
        alert("조회조건을 입력하세요.");
        ibx_coSnm.focus();
        return false;
    }
    return true;
};

/**
 * 기업목록 조회
 */
scwin.search = function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    const reqMap = {
        coSnm: ibx_coSnm.getValue(), // 기업명
        corpRegTyp: sbx_corpRegTyp.getValue(), // 법인유형
        stdIndTyp: tbx_stdIndCd.getValue(), // 업종코드
        affCoCd: tbx_entprGrpCd.getValue(), // 기업집단코드
    };
    $c.sbm.execute(sbm_comList, reqMap);
};

/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.setParam = async function(v_Currow) {
    if (v_Currow === undefined) {
        v_Currow = dlt_comListRes.getRowPosition();
    }
    // var arrPar = new Array();
    // arrPar[0] = {
    //     CO_SNM: dlt_comListRes.getCellData(v_Currow, "coSnm"), //기업명	
    //     KIS_CD: dlt_comListRes.getCellData(v_Currow, "kisCd"), //기업코드	
    //     IND_PTTN: dlt_comListRes.getCellData(v_Currow, "indPttn") //업종유형
    // };

    // opener.fn_SetParKisCd(arrPar);
    // await $c.frame.CloseFrame();

    const res = dlt_comListRes.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};

/**
 * 업종검색 팝업 오픈
 */
scwin.stdIndSrchOpen = async function() {
    // await $c.frame.CreateDialogFrame("STD_IND_CD", "./ULDFIS00100_P2.gfm", "업종검색", 65, 90, 360 + 20, 460 + 40, "window");

    let url = "/ui/lst/fis/ULDFIS00102.xml";
    let popTitle = "업종검색";

    const opts = {
        id: "ULDFIS00102",
        popupName: popTitle,
        width: 400,
        height: 600,
        frameModal: "top",
    };

    const res = await $c.win.openPopup(url, opts);

    tbx_stdIndCd.setValue(res.stdIndCd); // 기업집단코드
    ibx_stdIndNm.setValue(res.stdIndNm); // 업종명

    // TODO: (확인) 기업집단 선택 후 바로 기업검색 하는 로직인데, 팝업닫히기 전에 알림창이 뜸
    // if (ibx_coSnm.getValue() != "") {
    //     scwin.fn_Search();
    // }
};

/**
 * 업종검색 팝업으로 값을 넘김.
 */
scwin.getParStdIndCd = function(arrPar) {

};

/**
 * 업종검색 팝업에서 값을 받음.
 */
scwin.setParStdIndCd = function(arrPar) {
    tbx_stdIndCd.setValue(arrPar[0].STD_IND_CD); // 업종코드
    ibx_stdIndNm.setValue(arrPar[0].STD_IND_NM); // 업종명

};

/**
 * 기업집단검색 팝업 오픈
 */
scwin.affCoCdSrchOpen = async function() {
    // await $c.frame.CreateDialogFrame("AFF_CD_CD", "./ULDFIS00100_P3.gfm", "기업집단검색", 360, 90, 226 + 20, 320 + 40, "window");

    let url = "/ui/lst/fis/ULDFIS00103.xml";
    let popTitle = "기업 검색";

    const opts = {
        id: "ULDFIS00103",
        popupName: popTitle,
        width: 500,
        height: 500,
        frameModal: "top",
    };

    const res = await $c.win.openPopup(url, opts);

    tbx_entprGrpCd.setValue(res.entprGrpCd); // 기업집단코드
    ibx_entprGrpNm.setValue(res.entprGrpNm); // 기업집단명
    // tbx_entprGrpTyp.setValue(res.entprGrpTyp); //기업집단유형

    if (tbx_entprGrpCd.getValue() !== "") {
        scwin.search();
    }
};

/**
 * 기업집단검색 팝업으로 값을 넘김.
 */
scwin.getParAffCoCd = function() {
    let arrPar = new Array();
    arrPar[0] = ibx_entprGrpNm.getValue(); // 기업집단
    return arrPar;
};

/**
 * 기업집단검색 팝업에서 값을 받음.
 */
scwin.setParAffCoCd = function(arrPar) {
    tbx_entprGrpCd.setValue(arrPar[0].ENTPR_GRP_CD); // 기업집단코드
    ibx_entprGrpNm.setValue(arrPar[0].ENTPR_GRP_NM); // 기업집단명

};

scwin.gform_onload = function() {
};
